["init"] = {
["custom"] = "if not aura_env.region.soundAdded then\n    if C_AddOns.IsAddOnLoaded(\"LiquidMedia\") then\n        C_UnitAuras.AddPrivateAuraAppliedSound(\n            {\n                unitToken = \"player\",\n                spellID = 465325, -- Hot Hot Heat\n                soundFileName = \"Interface\\\\AddOns\\\\LiquidMedia\\\\TTS\\\\Sara\\\\beam on you.mp3\",\n                outputChannel = \"master\"\n            }\n        )\n    elseif C_AddOns.IsAddOnLoaded(\"AuraUpdater\") then\n        C_UnitAuras.AddPrivateAuraAppliedSound(\n            {\n                unitToken = \"player\",\n                spellID = 465325, -- Hot Hot Heat\n                soundFileName = \"Interface\\\\AddOns\\\\AuraUpdater\\\\Media\\\\TTS\\\\Sara\\\\beam on you.mp3\",\n                outputChannel = \"master\"\n            }\n        )\n    end\n    \n    aura_env.region.soundAdded = true\nend",
["do_custom"] = true,
