["init"] = {
["custom"] = "aura_env.inventionOrderHeroic = {\n    \"Beams\",\n    \"Rockets\",\n    \"Magnets\",\n    \n    \"|cff824dffBeams|r\",\n    \"|cff824dffBeams|r + Rockets\",\n    \"|cff824dffBeams|r + Magnets\",\n    \n    \"|cff824dffBalls|r\",\n    \"|cff824dffBalls|r + Magnets\",\n    \"|cff824dffBeams|r + |cff824dffBalls|r + Magnets\"\n}\n\naura_env.inventionOrderMythic = {\n    \"Beams\",\n    \"Rockets\",\n    \"Magnets\",\n    \n    \"|cff824dffBeams|r\",\n    \"|cff824dffBeams|r + Rockets\",\n    \"|cff824dffBeams|r + Magnets\",\n    \n    \"|cff824dffBalls|r\",\n    \"|cff824dffBalls|r + Magnets\",\n    \"|cff824dffBeams|r + |cff824dffBalls|r + Magnets\"\n}",
["do_custom"] = true,
