["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 4,\n            expirationTime = GetTime() + 4,\n            inventions = aura_env.inventionOrderMythic[math.random(#aura_env.inventionOrderMythic)],\n            autoHide = true\n        }\n    elseif event == \"UNIT_SPELLCAST_START\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        \n        if spellID == 473276 then -- Activate Inventions!\n            aura_env.count = aura_env.count + 1\n            \n            local inventions = aura_env.inventionOrder[aura_env.count]\n            \n            if inventions then\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 4,\n                    expirationTime = GetTime() + 4,\n                    inventions = aura_env.inventionOrder[aura_env.count],\n                    autoHide = true\n                }\n                \n                return true\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        local _, _, difficultyID = ...\n        \n        aura_env.inventionOrder = difficultyID == 16 and aura_env.inventionOrderMythic or aura_env.inventionOrderHeroic\n        aura_env.count = 0\n    end\nend",
