["glowLength"] = 10,
["customText"] = "function()\n    if aura_env.states[1] and aura_env.states[1].show then\n        local data = aura_env.states[1].data\n        if data and data.value then\n            local current = aura_env.formatNumber(data.value) or 0\n            local percent = data.percentDisplay\n            local text = format(\"%s (%s)\", current, percent)\n            if aura_env.config.color then\n                text = aura_env.color(text, data.percent)\n            end\n            return text\n        elseif aura_env.states[1].destGUID then\n            return \"|cFF00FFFFre-target|r\"\n        end\n    end\nend\n\n\n\n\n",
["zoom"] = 0.3,
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.region.destGUID = nil\n\nlocal c = aura_env.config\naura_env.formatNumber = function(value)\n    if not value or type(value) ~= \"number\" then return end\n    if c.format == 1 then\n        if value > 999999999 then\n            value = string.format(\"%.2fB\", value/1000000000)\n        elseif value > 999999 then\n            value = string.format(\"%.2fM\", value/1000000)   \n        elseif value > 99999 then\n            value = string.format(\"%.0fK\", value/1000)\n        elseif value > 999 then\n            value = string.format(\"%.1fK\", value/1000)\n        elseif value <= 0 then\n            value = 0\n        end \n    else\n        if value > 999999999 then\n            value = (\"%d,%03d,%03d,%03d\"):format(floor(value/1000000000), floor(value/1000000)%1000, floor(value/1000)%1000, value%1000)\n        elseif value > 999999 then\n            value = (\"%d,%03d,%03d\"):format(floor(value/1000000), floor(value/1000)%1000, value%1000)\n        elseif value > 999 then\n            value = (\"%d,%03d\"):format(floor(value/1000), value%1000)\n        elseif value <= 0 then\n            value = 0\n        end\n    end\n    \n    return value\nend\n\naura_env.subEvents = {\n    [\"SWING_DAMAGE\"] = function(value, total, ...) \n        local amount = select(12, ...)\n        value = value - amount\n        return value < 0 and 0 or value\n    end,\n    [\"SWING_HEAL\"] = function(value, total, ...)\n        local amount = select(12, ...)\n        value = value + amount\n        return value > total and total or value\n    end,\n    [\"RANGE_DAMAGE\"] = function(value, total, ...)\n        local amount = select(15, ...)\n        value = value - amount\n        return value < 0 and 0 or value\n    end,\n    [\"RANGE_HEAL\"] = function(value, total, ...)\n        local amount = select(15, ...)\n        value = value + amount\n        return value > total and total or value\n    end,\n    [\"ENVIRONMENTAL_DAMAGE\"] = function(value, total, ...)\n        local amount = select(13, ...)\n        value = value - amount\n        return value < 0 and 0 or value\n    end,\n    [\"ENVIROMENTAL_HEAL\"] = function(value, total, ...)\n        local amount = select(13, ...)\n        value = value + amount\n        return value > total and total or value\n    end,\n    [\"SPELL_DAMAGE\"] = function(value, total, ...)\n        local amount = select(15, ...)\n        value = value - amount\n        return value < 0 and 0 or value\n    end,\n    [\"SPELL_HEAL\"] = function(value, total, ...)\n        local amount = select(15, ...)\n        value = value + amount\n        return value > total and total or value\n    end,\n    [\"SPELL_PERIODIC_DAMAGE\"] = function(value, total, ...)\n        local amount = select(15, ...)\n        value = value - amount\n        return value < 0 and 0 or value\n    end,\n    [\"SPELL_PERIODIC_HEAL\"] = function(value, total, ...)\n        local amount = select(15, ...)\n        value = value + amount\n        return value > total and total or value\n    end,\n}\n--hardcode color until i figure out how to make conditions properly work with table data from state\naura_env.color = function(text, value)\n    text = text or \"\"\n    if not value then return text end\n    \n    local hex = value >= 75 and \"|cFF00FF00\"\n    or value >= 50 and \"|cFFFFFF00\"\n    or value >= 25 and \"|cFFFF7F00\"\n    or \"|cFFFF0000\"\n    \n    return format(\"%s%s|r\", hex, text)\nend\n\naura_env.data = {}\n\n\n\n",
["do_custom"] = true,
},
