["custom"] = "function(allstates, event, ...)\n    if event == \"UNIT_TARGET\" then\n        local unit = ...\n        \n        if not UnitExists(unit) then return end\n        \n        local _, _, _, _, endTimeMS, _, _, _, spellID = UnitCastingInfo(unit)\n        \n        if spellID and spellID == 1219039 then -- Ionization\n            local targetUnit = unit .. \"target\"\n            \n            if not UnitExists(targetUnit) then return end\n            if not UnitIsUnit(targetUnit, \"player\") then return end\n            \n            local GUID = UnitGUID(unit)\n            \n            if not GUID then return end\n            \n            local state = allstates[GUID]\n            \n            if not state then\n                allstates[GUID] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 1,\n                    expirationTime = endTimeMS / 1000,\n                    autoHide = true\n                }\n                \n                return true\n            end\n        end\n    end\nend",
