["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 4.5,\n            expirationTime = GetTime() + 4.5,\n            additionalProgress = {\n                {\n                    min = 1.5,\n                    max = 3,\n                },\n                {\n                    min = 0,\n                    max = 1.5\n                }\n            }\n        }\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and destGUID == WeakAuras.myGUID and spellID == 1216509 then -- Screw Up\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 4.5,\n                expirationTime = GetTime() + 4.5,\n                additionalProgress = {\n                    {\n                        min = 1.5,\n                        max = 3,\n                    },\n                    {\n                        min = 0,\n                        max = 1.5\n                    }\n                },\n                autoHide = true\n            }\n            \n            return true\n        end\n    end\nend",
