["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        for i = 1, 6 do\n            allstates[i] = {\n                show = true,\n                changed = true,\n                unit = \"player\",\n                mark = string.format(\"{rt%d}\", i),\n                index = i\n            }\n        end\n    elseif event == \"LIQUID_CLUSTER_MINE_LIST\" then\n        local mines = ...\n        \n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        for mineGUID, info in pairs(mines) do\n            local targetGUID = info.targetGUID\n            local targetUnit = targetGUID and aura_env.GUIDToUnit[targetGUID]\n            local mark = info.mark\n            \n            allstates[mineGUID] = {\n                show = true,\n                changed = true,\n                unit = targetUnit,\n                mark = mark and string.format(\"{rt%d}\", mark),\n                index = mark or 100\n            }\n        end\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.GUIDToUnit = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            local GUID = UnitGUID(unit)\n            \n            aura_env.GUIDToUnit[GUID] = unit\n        end\n    end\nend",
