["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.positions = {\n    {0.28, 0.15}, -- Star\n    {0.28, 0.37}, -- Circle\n    {0.28, 0.68}, -- Diamond\n    {0.28, 0.89}, -- Triangle\n    \n    {0.72, 0.15}, -- Moon\n    {0.72, 0.37}, -- Square\n    {0.72, 0.68}, -- Cross\n    {0.72, 0.89}, -- Skull\n}",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    color = {\n        display = \"Color\",\n        type = \"select\",\n        values = {\n            RED = \"Red\",\n            BLUE = \"Blue\",\n            ORANGE = \"Orange\"\n        }\n    },\n    order = {\n        display = \"Order\",\n        type = \"number\"\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        for _, i in ipairs({3, 4, 7, 8}) do\n            allstates[i] = {\n                show = true,\n                changed = true,\n                position = aura_env.positions[i],\n                mark = string.format(\"{rt%d}\", i),\n                unit = \"player\",\n                color = \"ORANGE\",\n                order = i\n            }\n        end\n    elseif event == \"LIQUID_FOOT_BLASTER_ASSIGNMENT\" then\n        local set, assignments, isMythic = ...\n        \n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        for i, assignment in ipairs(assignments) do\n            local marker = assignment.marker\n            \n            allstates[i] = {\n                show = true,\n                changed = true,\n                position = aura_env.positions[assignment.marker],\n                mark = string.format(\"{rt%d}\", marker),\n                unit = aura_env.GUIDToUnit[assignment.GUID],\n                color = assignment.color or \"ORANGE\",\n                order = i,\n                displayOrder = assignment.order\n            }\n        end\n        \n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.GUIDToUnit = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            local GUID = UnitGUID(unit)\n            \n            aura_env.GUIDToUnit[GUID] = unit\n        end\n    end\nend",
