["Foot-Blaster soak assignments"] = {
["outline"] = "OUTLINE",
["wagoID"] = "Jvpud9Ahy",
["authorOptions"] = {
{
["type"] = "toggle",
["key"] = "tts",
["default"] = true,
["useDesc"] = false,
["name"] = "Text-to-speech",
