["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local assignmentIndex = math.random(5)\n        local assignment = aura_env.textPositions[assignmentIndex]\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 8,\n            expirationTime = GetTime() + 8,\n            assignment = assignment,\n            autoHide = true\n        }\n    elseif event == \"GALLYWIX_SPREAD_ASSIGN\" then\n        local assignmentIndex = ...\n        local assignment = aura_env.textPositions[assignmentIndex]\n        \n        if not allstates[\"\"] then\n            LiquidWeakAuras:PlaySound(assignment)\n        end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 8,\n            expirationTime = GetTime() + 8,\n            assignment = assignment,\n            autoHide = true\n        }\n        \n        return true\n    end\nend",
