{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function()\n    local tank = false;\n    local dps = false;\n    local healer = false;\n    local posTank, posHealer, posDps = UnitGetAvailableRoles(\"player\")\n    if posDps then\n        dps = aura_env.config.dps;\n    end\n    if posTank then\n        tank = aura_env.config.tank;\n    end\n    if posHealer then\n        healer = aura_env.config.healer;\n    end\n    if not (tank or healer or dps) then\n        local role = UnitGroupRolesAssigned(\"player\")\n        if role == \"NONE\" then\n            role = GetSpecializationRole(GetSpecialization());\n        end\n        if role == \"TANK\" then\n            tank = true;\n        elseif role == \"DAMAGER\" then\n            dps = true;\n        elseif role == \"HEALER\" then\n            healer = true;\n        end\n    end\n    if LFDRoleCheckPopupRoleButtonTank.checkButton:IsEnabled() then\n        LFDRoleCheckPopupRoleButtonTank.checkButton:SetChecked(tank);\n    end\n    if LFDRoleCheckPopupRoleButtonHealer.checkButton:IsEnabled() then\n        LFDRoleCheckPopupRoleButtonHealer.checkButton:SetChecked(healer);\n    end\n    if LFDRoleCheckPopupRoleButtonDPS.checkButton:IsEnabled() then\n        LFDRoleCheckPopupRoleButtonDPS.checkButton:SetChecked(dps);\n    end\n    LFDRoleCheckPopupAcceptButton:Enable();\n    LFDRoleCheckPopupAcceptButton:Click();\nend\n\n\n",
