["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        local classFileName = UnitClassBase(\"player\")\n        \n        return string.format(\"|c%s%s|r\", RAID_CLASS_COLORS[classFileName].colorStr, string.sub(UnitName(\"player\"), 1, 8))\n    end\nend",
