["Earthshaker Gaol assignments (heroic)"] = {
["outline"] = "OUTLINE",
["wagoID"] = "Jvpud9Ahy",
["parent"] = "Mug'Zee, Heads of Security - Assignments",
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    local expirationTime = aura_env.state.expirationTime\n    local remaining = expirationTime - GetTime() - 0.01\n    \n    if not aura_env.lastExpirationTime or expirationTime ~= aura_env.lastExpirationTime then\n        aura_env.lastExpirationTime = expirationTime\n        aura_env.next = nil\n    end\n    \n    if remaining > 0 then\n        if not aura_env.next or remaining < aura_env.next then\n            aura_env.next = math.floor(remaining)\n            \n            SendChatMessage(string.format(\"%s %d\", aura_env.state.assignment, math.ceil(remaining)))\n        end\n    end\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "update",
["url"] = "https://wago.io/LiquidUndermine/4",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.spellID = 472631\naura_env.duration = 6\naura_env.assignments = {\n    \"Left\",\n    \"Right\"\n}\naura_env.tts = {\n    \"Left\",\n    \"Right\"\n}",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.duration - 0.2,\n            expirationTime = GetTime() + aura_env.duration - 0.2,\n            assignment = aura_env.assignments[math.random(2)],\n            autoHide = true\n        }\n    elseif event == \"LIQUID_ASSIGNMENT_EVENT\" then\n        local id = ...\n        \n        if id ~= aura_env.id then return end\n        \n        LiquidWeakAuras:SortTable(aura_env.affected)\n        \n        local myAssignment = tIndexOf(aura_env.affected, WeakAuras.myGUID)\n        \n        if myAssignment then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = aura_env.duration - 0.2,\n                expirationTime = GetTime() + aura_env.duration - 0.2,\n                assignment = aura_env.assignments[myAssignment],\n                autoHide = true\n            }\n            \n            local tts = aura_env.tts[myAssignment]\n            \n            if tts then\n                LiquidWeakAuras:PlaySound(tts)\n            end\n        end\n        \n        aura_env.affected = {}\n        \n        return true\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == aura_env.spellID then\n            table.insert(aura_env.affected, destGUID)\n            \n            if #aura_env.affected == 1 then\n                local id = aura_env.id\n                \n                C_Timer.After(0.2, function() WeakAuras.ScanEvents(\"LIQUID_ASSIGNMENT_EVENT\", id) end)\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.affected = {}\n        aura_env.GUIDToUnit = {}\n        \n        for unit in WA_IterateGroupMembers() do\n            aura_env.GUIDToUnit[UnitGUID(unit)] = unit\n        end\n    end\nend",
