["anchorFrameFrame"] = "WeakAuras:Class Power Bar",
["parent"] = "Buffs and Debuffs   ",
["displayText_format_c1_format"] = "none",
["anchorFrameType"] = "SELECTFRAME",
["useCooldownModRate"] = true,
["displayText"] = "%c",
