["init"] = {
["custom"] = "-- Configuration\naura_env.useShortNumbers = true\n\n-- Initialization\naura_env.isKarmaOn = false\naura_env.maxValue = 0\naura_env.curValue = 0\naura_env.expires = 0\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_hide"] = "custom",
["custom_type"] = "status",
["subeventSuffix"] = "_CAST_START",
["events"] = "CLEU:SPELL_ABSORBED,CLEU:SPELL_AURA_APPLIED,CLEU:SPELL_AURA_REMOVED",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["customDuration"] = "function()\n    return 10, aura_env.expires\nend",
["customName"] = "function()\n    local value = aura_env.curValue\n    if value >= 1000000 then\n        value = (math.floor(value / 10000) / 100) .. \"m\"\n    elseif value >= 1000 then\n        value = math.floor(value / 1000) .. \"k\"\n    end\n    return value\nend",
["custom"] = "function(event, ...)\n    local _, message = ...\n    local destName = select(9, ...)\n    if destName then \n        local iPosS, iPosE = string.find(destName, \"-\")\n    end\n    if destName and iPosE then\n        local unitName = strsub(destName,1,iPosE-1)\n    end\n    \n    local playerName = UnitName(\"player\")\n    local realmName = GetRealmName(\"player\")\n    local fullPlayerName = string.gsub(playerName..\"-\"..realmName, \"%s\", \"\")\n    \n    if destName and (destName == playerName) then\n        if message == \"SPELL_ABSORBED\" then\n            local chk = select(12, ...)\n            local spellID, absorbed\n            if type(chk) == \"number\" then\n                spellID = select(19, ...)\n                absorbed = select(22, ...)\n            else\n                spellID = select(16, ...)\n                absorbed = select(19, ...)\n            end\n            if spellID == 122470 then\n                aura_env.curValue = math.max(aura_env.curValue - absorbed, 0)\n                if aura_env.curValue == 0 then\n                    aura_env.isKarmaOn = false\n                end\n                return aura_env.isKarmaOn\n            end\n        elseif message == \"SPELL_AURA_APPLIED\" then\n            local spellID = select(12, ...)\n            \n            if spellID == 122470 then\n                aura_env.maxValue = math.floor(UnitHealthMax(\"player\") * 0.5)\n                aura_env.curValue = aura_env.maxValue\n                aura_env.expires = GetTime() + 10\n                aura_env.isKarmaOn = true\n                return true\n            end\n        elseif message == \"SPELL_AURA_REMOVED\" then\n            local spellID = select(12, ...)\n            if spellID == 122470 then\n                aura_env.isKarmaOn = false\n                return false\n            end\n        end        \n    end\n    return false\nend",
["names"] = {
},
["check"] = "event",
["spellIds"] = {
},
["unit"] = "player",
["debuffType"] = "HELPFUL",
},
