["customText"] = "function()\n    local text1, text2, text3, text4 = \"\", \"\", \"\", \"\"\n    if aura_env.state and aura_env.state.current and aura_env.state.total then\n        \n        if aura_env.MDT then\n            if (aura_env.state.pullText or aura_env.state.mcpullText) and aura_env.state.totalMC > aura_env.state.currentMC then\n                if aura_env.state.mcpullCompare and aura_env.state.mcpullCompare  then\n                    text4 = aura_env.state.mcpullText\n                    if aura_env.state.pullCompare then\n                        text2 = aura_env.state.pullText\n                    end\n                end\n            end\n        end\n        \n        text1 = aura_env.state.current\n        if aura_env.finish then\n            text1 = aura_env.finishforces and aura_env.finish or \"\"\n            text2 = \"\"\n        end\n        if text2 ~= \"\" and text2 ~= 0 and text2 ~= aura_env.finish then\n            if aura_env.countD == 1 then\n                if aura_env.state.pullCompare <= 0 then\n                    text2 = \"|cFF00FF00(+\"..text2..\")|r\"\n                else\n                    text2 = \"(+\"..text2..\")\"\n                end\n            else\n                if aura_env.state.pullCompare <= 0 then\n                    text2 = \"|cFF00FF00(\"..text2..\")|r\"\n                else\n                    text2 = \"(\"..text2..\")\"\n                end\n            end\n        end\n        \n        if text4 ~= \"\" and text4 ~= 0 then\n            if aura_env.countD == 1 then\n                local symbol = aura_env.remaining and \"-\" or \"+\"\n                if aura_env.state.mcpullCompare <= 0 then\n                    text4 = \"|cFF00FF00(\"..symbol..text4..\")|r\"\n                else\n                    text4 = \"(\"..symbol..text4..\")\"\n                end\n            else\n                if aura_env.state.mcpullCompare <= 0 then\n                    text4 = \"|cFF00FF00(\"..aura_env.state.mcpullCompare..\")|r\"\n                else\n                    text4 = \"(\"..aura_env.state.mcpullCompare..\")\"\n                end\n            end\n        end\n        \n        \n        if aura_env.remaining then\n            if aura_env.totalC then\n                text3 = aura_env.state.mcCompare..\"/\"..aura_env.state.totalMC\n            else\n                text3 = aura_env.state.mcCompare\n            end\n        else\n            if aura_env.state.totalMC > 1 then\n                if aura_env.totalC then\n                    text3 = aura_env.state.currentMC..\"/\"..aura_env.state.totalMC\n                else\n                    text3 = aura_env.state.currentMC\n                end\n            end\n        end            \n        text1 = ((aura_env.display == 1 or aura_env.display == 2) and text1) or \"\"\n        text2 = ((aura_env.display == 1 or aura_env.display == 2) and text2) or \"\"\n        text3 = ((aura_env.display == 1 or aura_env.display == 3) and text3) or \"\"\n        text4 = ((aura_env.display == 1 or aura_env.display == 3) and text4) or \"\"\n        return text1, text2, text3, text4\n    end\n    if WeakAuras.IsOptionsOpen() then\n        if not C_ChallengeMode.GetActiveChallengeMapID() then\n            text1, text2, text3, text4 = aura_env.getoptionstext()\n        end\n        return text1, text2, text3, text4\n    end\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
