["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = math.random(20) * 10,\n            total = 200,\n            skipPosition = true\n        }\n    elseif event == \"TRIGGER\" then\n        if WeakAuras.IsOptionsOpen() then return end\n        \n        local _, triggerStates = ...\n        local triggerState = triggerStates and triggerStates[\"\"]\n        \n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        if not triggerState then return true end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = triggerState.value or 0,\n            total = triggerState.total or 200,\n            skipPosition = true\n        }\n        \n        return true\n    end\nend",
