["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"LIQUID_DISPEL_EVENT\" then\n        local spellID, GUID = ...\n        \n        if spellID ~= aura_env.spellID then return end\n        \n        if GUID == WeakAuras.myGUID then\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and destGUID == WeakAuras.myGUID and spellID == aura_env.spellID then\n            allstates[\"\"] = {\n                show = true,\n                changed = true\n            }\n            \n            return true\n        elseif subEvent == \"SPELL_AURA_REMOVED\" and destGUID == WeakAuras.myGUID and spellID == aura_env.spellID then\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    end\nend",
