["custom"] = "function(allstates, _, unit, _, spellID)\n    if spellID == 317605 then\n        local guid = UnitGUID(unit)\n        local npcID = select(6, strsplit(\"-\", guid))\n        if npcID == \"162744\" then\n            allstates[guid] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 2.3,\n                expirationTime = 2.3 + GetTime(),\n                autoHide = true,\n            }\n            return true\n        end\n    end\nend",
