["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        for i = 1, 2 do\n            allstates[i] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 15,\n                expirationTime = GetTime() + 15,\n                autoHide = true\n            }\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, sourceGUID, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 466248 then -- 1500-Pound \"Dud\"\n            allstates[destGUID] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 15,\n                expirationTime = GetTime() + 15,\n                autoHide = true\n            }\n            \n            return true\n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == 466248 then -- 1500-Pound \"Dud\"\n            local state = allstates[destGUID]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    end\nend",
